// 1.2.23.2-16 - the far-horizon layer of the fifteen frontier ecosystems.
//
// This is a pure data catalogue. It adds six cohorts, three specialists, three
// disturbances, two goods, three relict layers, twelve field notes in tiers
// 4-6, two recurring cycles and three rotating field commissions per family.
// The runtime remains the one existing annual ledger; no map, renderer, action
// set or save schema is duplicated here.

const freeze = Object.freeze;
const sp = (id, label, kind, cover, note) => freeze({ id, label, kind, cover, note });
const rar = (id, label, kind, note) => freeze({ id, label, kind, note });
const hz = (id, label, trigger, effect) => freeze({ id, label, trigger, effect });
const gd = (id, label, value, annual, note) => freeze({ id, label, value, annual, note });
const nt = (id, tier, label, detail, goal, at, goalLabel, gold, reward = {}) => freeze({
    id, tier, label, detail, goal, at, goalLabel, reward: freeze({ gold, ...reward }),
});
const cy = (id, label, detail, period, reward, phaseLabels) => freeze({
    id, label, detail, period, harvestPhase: 0, regenerationPhase: 2,
    phaseLabels: freeze(phaseLabels), reward: freeze(reward),
});
const cm = (id, label, detail, goal, at, reward) => freeze({
    id, label, detail, goal, at, reward: freeze(reward),
});

